const std::vector<Star>& BuiltinStars() {
    static const std::vector<Star> v = [] {
        std::vector<Star> out;
        out.reserve(_countof(kBuiltinStars));
        for (const auto& r : kBuiltinStars) {
            Star s;
            s.name = W(r.cn); s.nameEn = W(r.en);
            s.spectral = r.sp; s.con = r.con;
            s.ra = r.ra; s.dec = r.dec; s.mag = r.mag; s.hip = r.hip;
            s.info = W(r.info);
            s.source = "builtin";
            out.push_back(s);
        }
        return out;
    }();
    return v;
}

